from typing import List, Dict, Any, Optional
from enum import Enum

class ModerationCategory(str, Enum):
    TOXICITY = "TOXICITY"
    # Add other categories as needed, e.g., SEXUAL, HATE, VIOLENCE

class ModerationResult:
